/**
 * Private `dist/server` boundary regression (alpha15 S-01 / FR-01).
 *
 * The fixture's e2e server dispatches through the SHARED static boundary
 * (`dispatchRequest` from packages/router/src/vite/internal/static-serve.ts),
 * exactly like `oe start`, so this spec is the real-artifact form of the
 * boundary: the build's own `dist/server/index.js` and `dist/server/entry.js`
 * must answer 404 — on GET and HEAD, by their plain and percent-encoded
 * spellings — while the prerendered site and request-time routes keep serving.
 *
 * Prerequisites:
 *   pnpm run build     (fixture-local)
 *
 * Run: pnpm run e2e -- private-artifacts
 */
import { expect, test } from '@playwright/test';

test.describe('private dist/server boundary', () => {
  test('refuses the build private artifacts and keeps the site serving', async ({ request }) => {
    for (const pathname of [
      '/server/index.js',
      '/%73erver/index.js',
      '/server/entry.js',
      '/Server/index.js',
      '/server/',
    ]) {
      const response = await request.get(pathname);
      expect(response.status(), `GET ${pathname}`).toBe(404);
      const body = await response.text();
      expect(body, `GET ${pathname} must not carry the generated server entry`).not.toContain(
        'Generated by openElement build',
      );
    }

    // HEAD reports the same status without a body.
    const head = await request.head('/server/index.js');
    expect(head.status()).toBe(404);

    // The public artifact and a request-time route are untouched.
    const home = await request.get('/');
    expect(home.status()).toBe(200);
    expect(await home.text()).toContain('<html');

    const dynamic = await request.get('/panel-dynamic');
    expect(dynamic.status()).toBe(200);
  });
});
